#!/usr/bin/env node
// Builds the SQL that loads the Pond Quiz questions into Supabase, from a PRIVATE questions file.
// The questions and answers are never committed to this public repo: they live only in Supabase.
//
//   node scripts/build_pond_quiz_sql.mjs path/to/pond-quiz-questions.private.json
//     -> games/supabase/private/update_pond_quiz_questions.sql (git-ignored)
//   Then run update_pond_quiz.sql once, and that generated file, in the Supabase SQL editor.
//
// The questions file: { "questions": [ { id, question, answers[4], correct 0-3, source (PepecoinHub page or null),
// dated (true when the answer depends on a date) } ] }. The script checks it and stops on any mistake.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const OUT = 'games/supabase/private/update_pond_quiz_questions.sql';
const lit = s => (s == null ? 'null' : "'" + String(s).replace(/'/g, "''") + "'");
// asked only with a source on the site and no answer tied to a date
export const isActive = q => !!q.source && !q.dated;

// the mistakes in a questions file, as readable lines (empty: the file is fine)
export function validate(questions) {
  const bad = [], ids = new Set(), texts = new Set();
  if (!Array.isArray(questions) || !questions.length) return ['no questions'];
  for (const q of questions) {
    const at = (q && q.id) || JSON.stringify(q).slice(0, 40);
    if (!q || typeof q.id !== 'string' || !/^[a-z0-9_]{2,20}$/.test(q.id)) bad.push(at + ': id must be 2-20 of a-z 0-9 _');
    else if (ids.has(q.id)) bad.push(at + ': the same id twice'); else ids.add(q.id);
    if (!q || typeof q.question !== 'string' || q.question.trim().length < 9) bad.push(at + ': question missing');
    else { const k = q.question.toLowerCase().replace(/[^a-z0-9]/g, ''); if (texts.has(k)) bad.push(at + ': the same question twice'); texts.add(k); }
    if (!Array.isArray(q.answers) || q.answers.length !== 4 || q.answers.some(a => typeof a !== 'string' || !a.trim())) bad.push(at + ': needs 4 answers');
    else if (new Set(q.answers.map(a => a.trim().toLowerCase())).size !== 4) bad.push(at + ': two answers are the same');
    if (!Number.isInteger(q.correct) || q.correct < 0 || q.correct > 3) bad.push(at + ': correct must be 0-3');
    if (q.source != null && !/^https:\/\/pepecoinhub\.com\/([a-z-]*\.html)?$/.test(q.source)) bad.push(at + ': source must be a pepecoinhub.com page');
    if (typeof q.dated !== 'boolean') bad.push(at + ': dated must be true or false');
  }
  return bad;
}

export function buildSql(questions) {
  const rows = questions.map(q => `  (${lit(q.id)}, ${lit(q.question)}, array[${q.answers.map(lit).join(', ')}], ${q.correct}, ` +
    `${lit(q.source)}, ${isActive(q)})`);
  return `-- Pond Quiz question bank. PRIVATE: generated by scripts/build_pond_quiz_sql.mjs from the private questions file.
-- Never commit it. Run after update_pond_quiz.sql. Safe to run again: it updates the questions in place and switches off
-- questions that left the file (answers already given stay).
begin;
insert into games.quiz_questions (id, question, answers, correct, source, active) values
${rows.join(',\n')}
on conflict (id) do update set question = excluded.question, answers = excluded.answers, correct = excluded.correct,
  source = excluded.source, active = excluded.active;
update games.quiz_questions set active = false
  where id not in (${questions.map(q => lit(q.id)).join(', ')});
commit;
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const src = process.argv[2];
  if (!src) { console.error('usage: node scripts/build_pond_quiz_sql.mjs path/to/questions.private.json [out.sql]'); process.exit(2); }
  const data = JSON.parse(readFileSync(src, 'utf8'));
  const bad = validate(data.questions);
  if (bad.length) { console.error(bad.join('\n')); process.exit(1); }
  const root = new URL('../', import.meta.url), out = process.argv[3] ? new URL(process.argv[3], 'file://' + process.cwd() + '/') : new URL(OUT, root);
  mkdirSync(new URL('.', out), { recursive: true });
  writeFileSync(out, buildSql(data.questions));
  console.log('wrote', fileURLToPath(out), data.questions.length, 'questions,', data.questions.filter(isActive).length, 'active');
}
